val key = java.util.UUID.randomUUID().toString   // once per operation
val request = basicRequest
  .post(uri"$url")
  .header("Idempotency-Key", key)
  .body(payloadJson)

def attempt(n: Int): Response[Either[String, String]] = {
  val r = request.send(backend)                   // same request every time
  if (n <= 1 || r.code.isSuccess) r else attempt(n - 1)
}
